#include <cstdio>
#include <cstring>
using namespace std;

int main() {
    int n;
    while (scanf("%d", &n), n) {
        int ice[10] = {};
        for (int i = 0; i < n; ++i) {
            int a;
            scanf("%d", &a);
            ice[a]++;
        }

        char output[100]; // Buffer for output
        int index = 0;

        for (int i = 0; i < 10; ++i) {
            for (int j = 0; j < ice[i]; ++j) {
                output[index++] = '*';
            }
            if (!ice[i]) output[index++] = '-';
            output[index++] = '\n';
        }

        // Output the entire buffer at once
        printf("%.*s", index, output);
    }
}

