#include <cstdio>
#include <cstring>
using namespace std;

int main() {
    int n;
    while (scanf("%d", &n), n) {
        int ice[10] = {};
        for (int i = 0; i < n; ++i) {
            int a;
            scanf("%d", &a);
            ice[a]++;
        }

        // Use a single output string with predefined size
        char output[100]; // Buffer for output
        int index = 0;

        for (int i = 0; i < 10; ++i) {
            // Directly construct the output for each digit
            if (ice[i] > 0) {
                memset(output + index, '*', ice[i]); // Fill with '*' for ice[i] count
                index += ice[i];
            } else {
                output[index++] = '-'; // Add a '-' for no occurrences
            }
            output[index++] = '\n'; // New line after each digit
        }

        // Output the entire buffer at once
        fwrite(output, sizeof(char), index, stdout); // Using fwrite for better performance
    }
}

